    searchBuildings: {
        parameters: {
            query: {
                q: string;
                limit?: number;
                /** @description Inclusive contract-date lower bound. */
                from?: components["parameters"]["FromDate"];
                /** @description Inclusive contract-date upper bound. */
                to?: components["parameters"]["ToDate"];
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Buildings matching an address or cadastral identity. Matching ignores case and diacritics, expands "c."/"ul.", and reads "15A"/"15 a". Only buildings with a recorded sale or rental are known. A suffixed number ("15A") matches the parts registered with that suffix; when only the bare number is registered, matchType stays "address" and the items carry the bare number (or the suffix their other parts use, as on the building page). When the house number has no such building, matchType is "nearest" and items are the nearest numbers on the street. Register notes ("k.o. Bežigrad") and misspelt duplicates of a busier street are not listed in streets. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        items: {
                            cadastralMunicipalityCode: number;
                            buildingNumber: string;
                            settlement: string | null;
                            street: string | null;
                            houseNumber: string | null;
                            houseNumberSuffix: string | null;
                            longitude: number;
                            latitude: number;
                            saleCount: number;
                            rentalCount: number;
                            saleCounts: {
                                [key: string]: number;
                            };
                            rentalCounts: {
                                [key: string]: number;
                            };
                        }[];
                        count: number;
                        /** @enum {string} */
                        matchType: "address" | "nearest" | "street" | "cadastral" | "none";
                        /** @description House number read from the query ("100", "15a"). */
                        requestedHouseNumber: string | null;
                        /** @description Streets the query names (busiest first, at most three). */
                        streets: {
                            /** @description Most common registered spelling; empty for a rural settlement address. */
                            street: string;
                            settlement: string;
                            /** Format: int64 */
                            municipalityId: number | null;
                            buildingCount: number;
                            saleCount: number;
                            rentalCount: number;
                        }[];
                        /** @description Settlements (naselja) named by a query without a house number (at most five). */
                        settlements: {
                            /** Format: int64 */
                            id: number;
                            name: string;
                            /** Format: int64 */
                            municipalityId: number | null;
                            municipality: string;
                        }[];
                    };
                };
            };
            400: components["responses"]["Error"];
        };
    };
